import {FISH_SITES,FISH_HISTORY,FISH_PLANS} from './fish-case.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,value='',disabled=false)=>`<button class="fish-button" data-fish-action="${action}" data-fish-value="${value}" ${disabled?'disabled':''}>${text}</button>`;
export const fishSummary=t=>t.plan==='removed'?'已取出魚刺、重看檢查視野並確認病人感受。':t.plan==='observe'?'本次未見魚刺，症狀不明顯：觀察、門診追蹤。':t.plan==='ct'?'本次未見魚刺，症狀仍明顯：建議安排CT評估。':'本次未見魚刺，症狀明顯且本次評估疑在食道：安排胃鏡評估。';
function scopeArt(t,{oral=false,removed=false}={}){
  const site=t.activeSite||'vallecula',name=FISH_SITES.find(s=>s.id===site),showBone=!removed&&t.site&&(oral?t.site==='tonsils':t.activeSite===t.site),x=t.point.x*4.8,y=t.point.y*3.2;
  const anatomy=oral?'<ellipse cx="240" cy="160" rx="145" ry="107" fill="#5b393c"/><path d="M116 124Q240 70 364 124L343 146Q240 110 137 146Z" fill="#e0c4a3"/><ellipse cx="240" cy="205" rx="94" ry="41" fill="#b87e7a"/><path d="M213 87q27 61 54 0" fill="#c78b83"/><ellipse cx="151" cy="164" rx="18" ry="33" fill="#b07473"/><ellipse cx="329" cy="164" rx="18" ry="33" fill="#b07473"/>':site==='vallecula'?'<path d="M101 110Q240 48 379 110L350 172Q240 119 130 172Z" fill="#bc8d83"/><path d="M157 220Q240 100 323 220Q240 260 157 220" fill="#ce9b8c"/><path d="M163 185q40-25 58 3m38 0q20-28 58-3" stroke="#634343" stroke-width="13" fill="none"/>':site==='pyriform'?'<path d="M185 60Q240 210 295 60L290 239Q240 201 190 239Z" fill="#c09489"/><path d="M109 95q83 33 62 142-54-35-62-142m262 0q-83 33-62 142 54-35 62-142" fill="#624246" stroke="#b8847b" stroke-width="9"/>':site==='tonsils'?'<path d="M163 61q-60 100 0 198m154-198q60 100 0 198" stroke="#cc958a" stroke-width="17" fill="none"/><ellipse cx="158" cy="165" rx="31" ry="58" fill="#a9696d"/><ellipse cx="322" cy="165" rx="31" ry="58" fill="#a9696d"/><path d="M207 78q33 51 66 0" fill="#d2a194"/>':'<path d="M75 225Q240 53 405 225Q240 294 75 225" fill="#b77d79"/>'+Array.from({length:18},(_,i)=>`<ellipse cx="${145+i%6*38}" cy="${151+Math.floor(i/6)*30}" rx="12" ry="8" fill="#c99a8a" opacity=".65"/>`).join('');
  return`<div class="fish-view ${oral&&!t.headlamp?'fish-unlit':''}"><svg viewBox="0 0 480 320" role="img" aria-label="${oral?'頭燈下的口腔':name.name+' fiber'}簡化示意"><defs><radialGradient id="fishMucosa"><stop stop-color="#c29789"/><stop offset=".7" stop-color="#956b68"/><stop offset="1" stop-color="#251f2a"/></radialGradient><clipPath id="fishCircle"><ellipse cx="240" cy="160" rx="208" ry="142"/></clipPath></defs><rect width="480" height="320" fill="#182b34"/><g clip-path="url(#fishCircle)"><ellipse cx="240" cy="160" rx="208" ry="142" fill="url(#fishMucosa)"/>${anatomy}${showBone?`<path d="M${x-15} ${y+25}L${x+12} ${y-28}" stroke="#f5e9c3" stroke-width="5" stroke-linecap="round"/><path d="M${x+12} ${y-28}l-3 14" stroke="#cbbd98" stroke-width="2"/>`:''}${t.tool==='forceps'&&t.stage==='extract'?`<path d="M400 315L${x+14} ${y+18}m10 14L425 315" fill="none" stroke="#b9cccb" stroke-width="7"/><path d="M${x+14} ${y+18}l-15-18m25 32l-12-22" stroke="#e0e4d8" stroke-width="4"/>`:''}</g><text x="20" y="25" fill="#d3dbcd" font-size="12" letter-spacing="1">${oral?'HEADLAMP / ORAL VIEW':name.name.toUpperCase()}</text><text x="240" y="303" text-anchor="middle" fill="#c4cfc4" font-size="11">簡化遊戲視野</text></svg>${showBone&&t.stage==='scope'?`<button class="fish-bone ${t.found?'marked':''}" style="left:${t.point.x}%;top:${t.point.y}%" data-fish-action="mark" aria-label="標記可疑細長物">${t.found?'✓':''}</button>`:''}${t.stage==='extract'?`<button id="fishGrasp" class="fish-grasp" style="left:${t.point.x}%;top:${t.point.y}%" ${t.tool!=='forceps'?'disabled':''} aria-label="對準魚刺按住夾取"><span>按住夾取</span></button>`:''}</div>`;
}
export function fishHTML(t,message='',plans=FISH_PLANS){
  const s=t.stage,p=t.patient,groups=['問病史','檢查','處理','交代'],group=s==='history'?0:['oral','scope'].includes(s)?1:['extract','recheck','plan'].includes(s)?2:3;
  let title='',body='';
  if(s==='history'){title='先把這口魚的故事問清楚。';body=`<div class="fish-history">${FISH_HISTORY.map(q=>`<section>${btn((t.asked.includes(q.id)?'✓ ':'')+q.text,'history',q.id,t.asked.includes(q.id))}${t.asked.includes(q.id)?`<p>病人：「${esc(q.id==='fish'?p.fish:p[q.id])}」</p>`:''}</section>`).join('')}</div>${btn('戴頭燈，先看口腔 →','history-done','',t.asked.length<3)}`;}
  else if(s==='oral'){title='頭燈戴好，先看口腔。';body=`<div class="fish-layout">${scopeArt(t,{oral:true})}<div class="fish-work">${btn(t.headlamp?'✓ 頭燈已戴好':'戴上頭燈','headlamp','',t.headlamp)}${btn(t.oralChecked?'✓ 口腔已檢查':'檢查口腔','oral-check','',!t.headlamp||t.oralChecked)}${t.oralChecked?`<p>${t.site==='tonsils'?'扁桃腺附近可見疑似細長魚刺，接著用fiber確認其他視野。':'這次口腔未看到明確魚刺，接著用fiber檢查。'}</p>`:''}${btn('拿 fiber，接續檢查 →','fiber','',!t.oralChecked)}</div></div>`;}
  else if(s==='scope'){title='Fiber，一個位置一個位置看。';body=`<nav class="fish-sites" aria-label="Fiber檢查位置">${FISH_SITES.map(site=>`<button data-fish-action="view" data-fish-value="${site.id}" aria-pressed="${t.activeSite===site.id}"><b>${t.inspected.includes(site.id)?'✓ ':''}${site.name}</b><span>${site.zh}</span></button>`).join('')}</nav><div class="fish-layout">${t.activeSite?scopeArt(t):'<div class="fish-view fish-wait"><span>FIBER</span><p>選一個位置，打開視野。</p></div>'}<div class="fish-work"><b>${t.inspected.length} / 4 處已查看</b><p>${!t.activeSite?'上方四個位置都要看過。':t.activeSite===t.site?t.found?'已標記可疑魚刺。':'看看視野裡的細長物，點選標記。':'這個位置未見明確魚刺。'}</p>${btn('完成 fiber 檢查 →','scope-done','',t.inspected.length<4)}<small>查看與標記進度都會保留。</small></div></div>`;}
  else if(s==='extract'){title='看到了，拿魚刺鉗。';body=`<div class="fish-layout">${scopeArt(t)}<div class="fish-work"><p>已在 ${FISH_SITES.find(v=>v.id===t.site).name} 標記魚刺。</p><div class="fish-tools">${[{id:'forceps',text:'魚刺鉗'},{id:'cup',text:'Biopsy cup'},{id:'cotton',text:'棉棒'}].map(tool=>btn((t.tool===tool.id?'✓ ':'')+tool.text,'tool',tool.id,t.tool===tool.id)).join('')}</div><p>選好器械，對準視野中的魚刺按住夾取。</p><small>鍵盤可用 Tab 選取「按住夾取」後按 Enter。</small></div></div>`;}
  else if(s==='recheck'){title='取出後，再看一眼、再問一句。';body=`<div class="fish-layout">${scopeArt(t,{removed:true})}<div class="fish-work">${btn(t.rechecked?'✓ 已重看視野並詢問感受':'重看檢查視野，詢問病人感受','recheck','',t.rechecked)}${t.rechecked?'<p>本次視野未見原魚刺。病人：「刺刺的感覺有減輕了。」</p>':''}${btn('交代後續，整理紀錄 →','recheck-done','',!t.rechecked)}</div></div>`;}
  else if(s==='plan'){title='沒看到魚刺，下一步看這位的症狀。';body=`<div class="fish-decision"><section class="fish-case-note"><b>本次檢查</b><p>口腔與fiber四處檢查，未見明確魚刺。</p><b>病人的描述</b><p>「${esc(p.symptoms)}」</p><span>${t.variant==='mild'?'症狀不明顯':t.variant==='esophagus'?'症狀明顯 · 本次評估懷疑食道位置':'症狀仍明顯 · 本次尚未定位'}</span></section><div class="fish-plan">${plans.map(plan=>btn(plan.text,'plan',plan.id)).join('')}</div></div>`;}
  else if(s==='explain'){title='把結果與後續說清楚。';body=`<section class="fish-case-note"><b>${esc(p.name)} · 本次安排</b><p>${fishSummary(t)}</p></section><p class="fish-instructions">向病人說明檢查結果、後續安排，以及症狀變化時再回報評估。</p>${btn('完成說明與會診紀錄 ✓','finish')}`;}
  return`<span class="modal-tag">急診會診 · 2G 初診間</span><h2 id="modalTitle">${title}</h2><div class="fish-patient"><b>${esc(p.name)}</b><span>吃魚後異物感 · 初評呼吸平順</span></div><div class="fish-tracker">${groups.map((name,i)=>`<span class="${i===group?'active':''}">${i<group?'✓':i+1} ${name}</span>`).join('')}</div>${body}<p id="fishFeedback" class="fish-feedback" role="status">${esc(message)}</p><footer class="fish-footer"><small>科內娛樂的簡化情境</small><button id="fishLater" class="text-button">先離開，進度保留 →</button></footer>`;
}
export function bindFish(t,{act,later,active}){
  document.querySelectorAll('[data-fish-action]').forEach(b=>b.onclick=()=>act(b.dataset.fishAction,b.dataset.fishValue));
  const grasp=document.getElementById('fishGrasp');if(grasp){let timer;const clear=()=>{clearTimeout(timer);grasp.classList.remove('holding');};const commit=()=>{clear();if(grasp.isConnected&&active()&&t.stage==='extract')act('extract');};grasp.onpointerdown=e=>{if(grasp.disabled||e.button!==0)return;grasp.setPointerCapture(e.pointerId);clear();grasp.classList.add('holding');timer=setTimeout(commit,650);};grasp.onpointerup=grasp.onpointercancel=grasp.onblur=clear;grasp.onclick=e=>{if(e.detail===0&&!grasp.disabled)commit();};}
  document.getElementById('fishLater').onclick=later;
}
